SET @userId = (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com' LIMIT 1);

-- 메시지 삭제
DELETE FROM messages WHERE senderId = @userId OR recipientId = @userId;

-- 버그 리포트 삭제
DELETE FROM bug_reports WHERE userId = @userId;

-- 예약 삭제
DELETE FROM bookings WHERE studentId = @userId OR mentorId = @userId;

-- 리뷰 삭제
DELETE FROM reviews WHERE studentId = @userId OR mentorId = @userId;

-- 알림 삭제
DELETE FROM notifications WHERE userId = @userId;

-- 멘토 검증 삭제
DELETE FROM mentor_verifications WHERE userId = @userId;

-- 멘토 갤러리 삭제
DELETE FROM mentor_gallery WHERE userId = @userId;

-- 멘토 프로필 삭제
DELETE FROM mentor_profiles WHERE userId = @userId;

-- 사용자 계정 삭제
DELETE FROM users WHERE id = @userId;

